const ctx = $('When Called').first().json;
const opts = ctx.options ?? {};
const TH = Math.min(Math.max(parseInt(opts.silent_fix_threshold ?? 60, 10) || 60, 1), 100);
const cands = JSON.parse($input.first().json.stdout || '[]');
const art = `${ctx.run_dir}/diff/candidates.json`;
const rows = cands.filter((c) => c && c.key).map((c) => ({
  key: c.key, run_id: ctx.run_id, product: ctx.product, old_version: ctx.old_version, new_version: ctx.new_version,
  kind: c.kind, location: String(c.location ?? '').slice(0, 500), score: Number(c.score ?? 0), signals: c.signals ?? {},
  advisory_match: c.advisory_match ?? null,
  silent_fix: Number.isInteger(c.llm_likely_security_fix) && c.llm_likely_security_fix >= TH && !c.advisory_match,
  llm_bug_class: c.llm_bug_class ?? '', llm_summary: c.llm_summary ?? '', llm_confidence: c.llm_confidence ?? '',
  llm_likely_security_fix: Number.isInteger(c.llm_likely_security_fix) ? c.llm_likely_security_fix : null,
  llm_entry_point: c.llm_entry_point ?? '', artefact_path: art, rank: c.rank ?? null
}));
return [{ json: { n: rows.length, threshold: TH, rows: JSON.stringify(rows) } }];

const ctx = $('When Called').first().json;
const built = $('Build Rows').first().json;
const rows = JSON.parse(built.rows);
const fresh = new Set($input.all().map((i) => i.json.key).filter(Boolean));
const cut = (s, n) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const code = (s) => '`' + String(s).replace(/`/g, "'") + '`';
const llm = (r) => (r.llm_likely_security_fix ?? -1);
const top = [...rows].sort((a, b) => llm(b) - llm(a) || b.score - a.score).slice(0, 5);
const line = (r) => [
  `${r.silent_fix ? '🤫 ' : ''}${code(cut(r.location, 120))}`,
  `score ${r.score} · LLM ${r.llm_likely_security_fix ?? '–'}/100 · ${cut(r.llm_bug_class || 'unclassified', 60)}${r.advisory_match ? ` · ${r.advisory_match}` : ''}${fresh.has(r.key) ? '' : ' · seen before'}`,
  cut(r.llm_summary || 'no triage summary', 220)
].join('\n');
const silent = rows.filter((r) => r.silent_fix && fresh.has(r.key));
const st = ctx.stages ?? {};
const now = new Date().toISOString();
const embed = {
  title: cut(`🔍 Patch diff · ${ctx.product} ${ctx.old_version} → ${ctx.new_version}`, 256),
  color: silent.length ? 0xE74C3C : rows.length ? 0xE67E22 : 0x95A5A6,
  description: cut(top.length ? top.map(line).join('\n\n') : 'No candidate scored above zero.', 4000),
  fields: [
    { name: 'Candidates', value: String(rows.length), inline: true },
    { name: 'New findings', value: String(fresh.size), inline: true },
    { name: 'Silent fixes (new)', value: String(silent.length), inline: true },
    { name: 'Advisories in range', value: String(st.advisory?.advisories_relevant ?? '–'), inline: true },
    { name: 'Diff mode', value: String(st.diff?.mode ?? '–'), inline: true },
    { name: 'Artefacts', value: code(ctx.run_dir), inline: false }
  ],
  footer: { text: `PD · ${ctx.run_id}` },
  timestamp: now
};
const silentEmbed = silent.length ? {
  title: cut(`🤫 Silent fix candidates · ${ctx.product} ${ctx.new_version}`, 256),
  color: 0x9B111E,
  description: cut(silent.slice(0, 8).map(line).join('\n\n'), 4000),
  fields: [
    { name: 'Why', value: `LLM likely_security_fix ≥ ${built.threshold} and no matching advisory`, inline: false },
    { name: 'Candidates file', value: code(`${ctx.run_dir}/diff/candidates.json`), inline: false }
  ],
  footer: { text: `PD · ${ctx.run_id}` },
  timestamp: now
} : null;
const alerted = [...new Set([...top.map((r) => r.key), ...silent.map((r) => r.key)])].filter((k) => fresh.has(k));
return [{ json: {
  embed, silent_embed: silentEmbed, has_silent: silentEmbed !== null, alerted_keys: JSON.stringify(alerted),
  new_findings: fresh.size, silent_fixes: silent.length, candidates: rows.length
} }];

