const ctx = $('When Called').first().json;
const a = $('Alert Embeds').first().json;
const stages = { ...(ctx.stages ?? {}), alerts: { candidates: a.candidates, new_findings: a.new_findings, silent_fixes: a.silent_fixes } };
return [{ json: { ...ctx, stages } }];
